source:
OPENQASM 3.0;
include "stdgates.inc";
qubit a;
qubit b;
h a;
h a;
h a;
cx a, b;

qc:
!q = !qc.qubit
func.func @main()
    attributes {mqt.entry_point} {
  %a = qc.alloc : !q
  %b = qc.alloc : !q
  qc.h %a : !q
  qc.h %a : !q
  qc.h %a : !q
  qc.ctrl(%a)
    targets (%t = %b) {
    qc.x %t : !q
    qc.yield
  } : {!q}, {!q}
  qc.dealloc %a : !q
  qc.dealloc %b : !q
  return
}

optimized:
!q = !qco.qubit
func.func @main()
    attributes {mqt.entry_point} {
  %a = qco.alloc : !q
  %b = qco.alloc : !q
  %a1 = qco.h %a : !q
  %c, %d = qco.ctrl(%a1)
    targets (%t = %b) {
    %x = qco.x %t : !q
    qco.yield %x : !q
  } : ({!q}, {!q})
  qco.sink %c : !q
  qco.sink %d : !q
  return
}
